import{_ as a,o as n,c as e,a0 as i}from"./chunks/framework.t4Rf69I2.js";const g=JSON.parse('{"title":"CI/CD 流水线","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/ci-cd.md","filePath":"zh/guide/ci-cd.md","lastUpdated":1785233645000}'),p={name:"zh/guide/ci-cd.md"};function l(t,s,o,c,h,d){return n(),e("div",null,[...s[0]||(s[0]=[i(`<h1 id="ci-cd-流水线" tabindex="-1">CI/CD 流水线 <a class="header-anchor" href="#ci-cd-流水线" aria-label="Permalink to &quot;CI/CD 流水线&quot;">​</a></h1><p>go-cipher-cli 使用 <strong>GitHub Actions</strong> 实现全自动发布。当你推送一个 <code>v*</code> 格式的 tag（如 <code>v0.1.0</code>）时，流水线会自动完成编译、打包、签名、文档构建、部署的全过程。</p><p>工作流定义见 <a href="https://github.com/kulaiyin/go-cipher-cli/blob/main/.github/workflows/release.yml" target="_blank" rel="noreferrer"><code>.github/workflows/release.yml</code></a>。</p><h2 id="触发条件" tabindex="-1">触发条件 <a class="header-anchor" href="#触发条件" aria-label="Permalink to &quot;触发条件&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">on</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  push</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    tags</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;v*&#39;</span></span></code></pre></div><p>即任何形如 <code>v0.1.0</code>、<code>v1.2.3</code> 的 tag 推送都会触发。</p><h2 id="流水线步骤" tabindex="-1">流水线步骤 <a class="header-anchor" href="#流水线步骤" aria-label="Permalink to &quot;流水线步骤&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  push v* tag                                                    │</span></span>
<span class="line"><span>│      │                                                          │</span></span>
<span class="line"><span>│      ▼                                                          │</span></span>
<span class="line"><span>│  1. Checkout（fetch-depth: 0，goreleaser 需完整历史）            │</span></span>
<span class="line"><span>│      │                                                          │</span></span>
<span class="line"><span>│      ▼                                                          │</span></span>
<span class="line"><span>│  2. 设置 Go 环境                                                 │</span></span>
<span class="line"><span>│      │                                                          │</span></span>
<span class="line"><span>│      ▼                                                          │</span></span>
<span class="line"><span>│  3. 设置 Node 环境（VitePress 构建）                             │</span></span>
<span class="line"><span>│      │                                                          │</span></span>
<span class="line"><span>│      ▼                                                          │</span></span>
<span class="line"><span>│  4. goreleaser release（官方 goreleaser-action）                 │</span></span>
<span class="line"><span>│     ├─ 编译 linux/amd64 二进制                                   │</span></span>
<span class="line"><span>│     ├─ 生成 .deb                                                 │</span></span>
<span class="line"><span>│     └─ 创建 GitHub Release，上传 .deb / tar.gz / checksums       │</span></span>
<span class="line"><span>│      │                                                          │</span></span>
<span class="line"><span>│      ▼                                                          │</span></span>
<span class="line"><span>│  5. 导入 GPG 私钥（从 Secret GPG_SIGNING_KEY 解码）              │</span></span>
<span class="line"><span>│      │                                                          │</span></span>
<span class="line"><span>│      ▼                                                          │</span></span>
<span class="line"><span>│  6. 运行 scripts/publish_repo.sh                                │</span></span>
<span class="line"><span>│     ├─ 生成 dists/ pool/ Release InRelease                      │</span></span>
<span class="line"><span>│     └─ 用导入的 key 签名                                         │</span></span>
<span class="line"><span>│      │                                                          │</span></span>
<span class="line"><span>│      ▼                                                          │</span></span>
<span class="line"><span>│  7. 导出 GPG 公钥到 repo/repo.gpg.key                            │</span></span>
<span class="line"><span>│      │                                                          │</span></span>
<span class="line"><span>│      ▼                                                          │</span></span>
<span class="line"><span>│  8. 构建 VitePress 文档站（npm ci &amp;&amp; npm run docs:build）        │</span></span>
<span class="line"><span>│      │                                                          │</span></span>
<span class="line"><span>│      ▼                                                          │</span></span>
<span class="line"><span>│  9. 聚合部署内容（文档 + APT 仓库）                               │</span></span>
<span class="line"><span>│      │                                                          │</span></span>
<span class="line"><span>│      ▼                                                          │</span></span>
<span class="line"><span>│  10. 部署到 gh-pages 分支                                        │</span></span>
<span class="line"><span>│      ├─ 文档站 → 根路径                                          │</span></span>
<span class="line"><span>│      └─ APT 仓库 (repo/) → /apt 子路径                           │</span></span>
<span class="line"><span>└────────────────────────────────────────────────────────────────┘</span></span></code></pre></div><h2 id="发布版本号" tabindex="-1">发布版本号 <a class="header-anchor" href="#发布版本号" aria-label="Permalink to &quot;发布版本号&quot;">​</a></h2><p>版本号来源于 <strong>git tag</strong>：</p><ul><li>tag <code>v0.1.0</code> → goreleaser 产出 <code>go-cipher-cli_0.1.0_linux_amd64.deb</code></li><li>同时该版本写入 APT 仓库的 <code>Packages</code> 索引</li></ul><p>因此发版的唯一动作就是打 tag：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tag</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v0.1.0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v0.1.0</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 此后全自动，无需干预</span></span></code></pre></div><h2 id="签名密钥管理" tabindex="-1">签名密钥管理 <a class="header-anchor" href="#签名密钥管理" aria-label="Permalink to &quot;签名密钥管理&quot;">​</a></h2><p>GPG 私钥通过 <strong>GitHub Repository Secret</strong> 注入，私钥本身永远不会进入代码库。</p><h3 id="生成或复用-gpg-key" tabindex="-1">生成或复用 GPG key <a class="header-anchor" href="#生成或复用-gpg-key" aria-label="Permalink to &quot;生成或复用 GPG key&quot;">​</a></h3><p>本地生成（如已有可复用）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gpg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --gen-key</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 记下生成的 Key ID，例如 9E38A2B39666B218</span></span></code></pre></div><h3 id="导出私钥并-base64-编码" tabindex="-1">导出私钥并 base64 编码 <a class="header-anchor" href="#导出私钥并-base64-编码" aria-label="Permalink to &quot;导出私钥并 base64 编码&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gpg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --armor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --export-secret-keys</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 9E38A2B39666B218</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> base64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -w0</span></span></code></pre></div><p><code>base64 -w0</code> 输出单行，避免 Secret 里出现换行导致导入失败。</p><h3 id="配置-github-secret" tabindex="-1">配置 GitHub Secret <a class="header-anchor" href="#配置-github-secret" aria-label="Permalink to &quot;配置 GitHub Secret&quot;">​</a></h3><ol><li>浏览器打开 <code>https://github.com/kulaiyin/go-cipher-cli/settings/secrets/actions</code></li><li>点击 <code>New repository secret</code></li><li><strong>Name</strong>：<code>GPG_SIGNING_KEY</code></li><li><strong>Value</strong>：粘贴上一步的 base64 输出</li><li>保存</li></ol><p>同时确保 <code>repo/conf/distributions</code> 里的 <code>SignWith:</code> 与该 Key ID 一致（当前为 <code>9E38A2B39666B218</code>）。CI 的 <code>publish_repo.sh</code> 会自动读取这个值并用导入的私钥签名。</p><div class="warning custom-block"><p class="custom-block-title">私钥安全</p><p>私钥泄露后任何人都能伪造你的仓库签名。请：</p><ul><li>仅在 GitHub Secret 中存储，不要写入任何文件或日志</li><li>定期轮换（生成新 key，更新 Secret，重新发布一次让客户端导入新公钥）</li></ul></div><h3 id="轮换密钥" tabindex="-1">轮换密钥 <a class="header-anchor" href="#轮换密钥" aria-label="Permalink to &quot;轮换密钥&quot;">​</a></h3><ol><li>本地生成新 key。</li><li>更新 <code>repo/conf/distributions</code> 的 <code>SignWith:</code> 为新 Key ID。</li><li>更新 GitHub Secret <code>GPG_SIGNING_KEY</code>。</li><li>重新触发一次发布，<code>repo.gpg.key</code> 会自动更新为新公钥。</li><li>通知客户端重新执行公钥导入步骤（<code>curl ... | sudo gpg --dearmor</code>）。</li></ol><h2 id="开启-github-pages-首次部署" tabindex="-1">开启 GitHub Pages（首次部署） <a class="header-anchor" href="#开启-github-pages-首次部署" aria-label="Permalink to &quot;开启 GitHub Pages（首次部署）&quot;">​</a></h2><p>首次发布成功后，<code>gh-pages</code> 分支会被创建。需在仓库设置中开启 Pages：</p><ol><li>浏览器打开 <code>https://github.com/kulaiyin/go-cipher-cli/settings/pages</code></li><li><strong>Source</strong> 选择 <code>Deploy from a branch</code></li><li><strong>Branch</strong> 选 <code>gh-pages</code>，目录选 <code>/ (root)</code></li><li>保存</li></ol><p>几分钟后即可访问 <code>https://kulaiyin.github.io/go-cipher-cli/</code>。</p><h2 id="本地预览发布产物" tabindex="-1">本地预览发布产物 <a class="header-anchor" href="#本地预览发布产物" aria-label="Permalink to &quot;本地预览发布产物&quot;">​</a></h2><p>无需真的 push tag，可在本地复现整个流程：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. 打包</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/package.sh</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. 生成 APT 仓库</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/publish_repo.sh</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. 本地预览文档站</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span></span></code></pre></div><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong><code>goreleaser: command not found</code></strong>：CI 使用官方 <code>goreleaser-action</code>，无需手工安装；本地可执行 <code>go install github.com/goreleaser/goreleaser@latest</code>。</li><li><strong><code>reprepro: command not found</code></strong>：<code>publish_repo.sh</code> 会自动回退到 apt-ftparchive，详见 <a href="./apt-repo">APT 仓库与 GitHub Pages</a> 的方案 C。</li><li><strong>签名失败 / <code>InRelease</code> 报错</strong>：先用 <code>gpg --gen-key</code> 生成密钥，并把 <code>repo/conf/distributions</code> 中的 <code>SignWith:</code> 设置为真实 Key ID。</li><li><strong>CI 中签名失败</strong>：检查 Secret <code>GPG_SIGNING_KEY</code> 是否配置、是否为 <code>base64 -w0</code> 单行格式，以及 <code>SignWith</code> 是否一致。</li><li><strong>客户端 <code>NO_PUBKEY</code> 报错</strong>：未正确导入发布者公钥，或公钥已轮换，请按 <a href="./installation">安装指南</a> 重新导入。</li><li><strong>客户端 <code>Could not handshake</code> / 连接被重置</strong>：通常是 <code>*.github.io</code> 被网络干扰（如 GFW）。需为 apt 配置代理，或改用 jsDelivr CDN 镜像源，或直接从 GitHub Release 下载 <code>.deb</code> 手工安装。</li><li><strong>gh-pages 未更新</strong>：Pages 未开启或分支选错。在 Settings → Pages 确认选 <code>gh-pages</code> 分支。</li></ul>`,36)])])}const k=a(p,[["render",l]]);export{g as __pageData,k as default};
